/**
 * Source of `_router.tsx`, written into the designs directory once and never overwritten.
 * Pages import it to navigate. It is ordinary React with no ultrapaint import: inside the
 * preview it finds `window.__ED_ROUTER__` and lets the editor hold the route, and anywhere
 * else it falls back to the browser's own history, so a page still works where it ships.
 */
export const ROUTER_MODULE_FILE = "_router.tsx";

export const routerModuleSource = `/**
 * Navigation between the pages of this space. Generated by ultrapaint; edit it if you like,
 * it is never overwritten.
 *
 *   import { Link, useNavigate, useParams, useRoute } from "./_router.tsx";
 *
 *   <Link to="/settings/billing">Billing</Link>
 *   const navigate = useNavigate();
 *   navigate("settings/billing.tsx");   // a page file works as well as a route
 */
import {
  type AnchorHTMLAttributes,
  type MouseEvent,
  useCallback,
  useSyncExternalStore,
} from "react";

export interface RouterState {
  readonly params: Readonly<Record<string, string>>;
  readonly route: string;
}

interface Router {
  navigate: (to: string, options?: { replace?: boolean }) => void;
  state: () => RouterState;
  subscribe: (listener: () => void) => () => void;
}

/** A route (\`/settings/billing\`) or a page file inside the space (\`settings/billing.tsx\`). */
export const href = (to: string): string => {
  if (to.startsWith("/")) {
    return to;
  }
  const path = to
    .replace(/\\.[jt]sx?$/, "")
    .replace(/(^|\\/)index$/, "$1")
    .replace(/\\/+$/, "");
  return \`/\${path}\`;
};

let fallbackState: RouterState = { params: {}, route: "/" };

/** Outside ultrapaint there is no editor to hold the route: the document's own URL does. */
const fallback: Router = {
  navigate: (to, options) => {
    const url = href(to);
    if (options?.replace) {
      window.history.replaceState(null, "", url);
    } else {
      window.history.pushState(null, "", url);
    }
    window.dispatchEvent(new PopStateEvent("popstate"));
  },
  state: () => {
    const route = window.location.pathname || "/";
    if (route !== fallbackState.route) {
      fallbackState = { params: {}, route };
    }
    return fallbackState;
  },
  subscribe: (listener) => {
    window.addEventListener("popstate", listener);
    return () => window.removeEventListener("popstate", listener);
  },
};

const SERVER: RouterState = { params: {}, route: "/" };

const router = (): Router => {
  const host = (globalThis as { __ED_ROUTER__?: Router }).__ED_ROUTER__;
  return host ?? fallback;
};

export const useRouter = (): RouterState =>
  useSyncExternalStore(
    (listener) => router().subscribe(listener),
    () => router().state(),
    () => SERVER
  );

export const useRoute = (): string => useRouter().route;

export const useParams = (): Readonly<Record<string, string>> =>
  useRouter().params;

export const useNavigate = () =>
  useCallback(
    (to: string, options?: { replace?: boolean }) =>
      router().navigate(to, options),
    []
  );

export interface LinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href"> {
  replace?: boolean;
  to: string;
}

export function Link({ to, replace, onClick, ...rest }: LinkProps) {
  const navigate = useNavigate();
  const press = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      rest.target === "_blank"
    ) {
      return;
    }
    event.preventDefault();
    navigate(to, { replace });
  };
  return <a href={href(to)} onClick={press} {...rest} />;
}
`;
